    private static readonly (Regex Regex, Func<Match, string> Build)[] Patterns =
    {
        // Interface
        P(@"^(\d+) ajustes disponíveis$", m => $"{m.Groups[1].Value} tweaks available"),
        P(@"^(\d+) de (\d+) ajustes selecionados$", m => $"{m.Groups[1].Value} of {m.Groups[2].Value} tweaks selected"),
        P(@"^(\d+) ajustes selecionados\. Um ponto de restauração é criado antes de qualquer alteração\.$", m => $"{m.Groups[1].Value} tweaks selected. A restore point is created before any change."),
        P(@"^(.+) MB podem ser liberados$", m => $"{m.Groups[1].Value} MB can be freed"),
        P(@"^(\d+) arquivos$", m => $"{m.Groups[1].Value} files"),
        P(@"^([\d.,]+ [KMGT]B) de ([\d.,]+ [KMGT]B)$", m => $"{m.Groups[1].Value} of {m.Groups[2].Value}"),
        P(@"^(\d+)% livre$", m => $"{m.Groups[1].Value}% free"),

        // Linhas do log de atividade: "[data] [NIVEL] mensagem"
        P(@"^(\[\d{4}-\d{2}-\d{2} [\d:]+\] \[\w+\]) (.+)$", m => $"{m.Groups[1].Value} {T(m, 2)}"),
        P(@"^Limpeza: (\d+) removidos, (\d+) preservados/ignorados, (.+) MB liberados\.$", m => $"Cleanup: {m.Groups[1].Value} removed, {m.Groups[2].Value} kept/skipped, {m.Groups[3].Value} MB freed."),
        P(@"^\[(OK|!!|FALHA|INFO|AVISO|IGNORADA|IGNORADO|ERRO)\] (.+)$", m => $"[{m.Groups[1].Value switch { "FALHA" => "FAILED", "ERRO" => "ERROR", "AVISO" => "WARNING", "IGNORADA" or "IGNORADO" => "SKIPPED", var v => v }}] {T(m, 2)}"),
        P(@"^(\[\d+/\d+\])\s+(.+)$", m => $"{m.Groups[1].Value} {T(m, 2)}"),
        P(@"^([\d.,]+) arquivos removidos$", m => $"{m.Groups[1].Value} files removed"),
        P(@"^([\d.,]+) ignorados$", m => $"{m.Groups[1].Value} skipped"),
        P(@"^([\d.,]+) MB liberados$", m => $"{m.Groups[1].Value} MB freed"),
        P(@"^Iniciando: (.+)$", m => $"Starting: {m.Groups[1].Value}"),
        P(@"^Execução concluída: (.+)$", m => $"Run finished: {m.Groups[1].Value}"),
        P(@"^Inicialização: (.+) (ativado|desativado)$", m => $"Startup: {m.Groups[1].Value} {(m.Groups[2].Value == "ativado" ? "enabled" : "disabled")}"),
        P(@"^Atualização (.+) verificada por SHA256; iniciando instalação silenciosa\.$", m => $"Update {m.Groups[1].Value} verified with SHA256; starting silent install."),
        P(@"^Não foi possível verificar atualizações: (.+)$", m => $"Could not check for updates: {m.Groups[1].Value}"),
        P(@"^Download direto de (.+) falhou: (.+)$", m => $"Direct download of {m.Groups[1].Value} failed: {m.Groups[2].Value}"),
        P(@"^Selecionado: (.+) MB$", m => $"Selected: {m.Groups[1].Value} MB"),
        P(@"^Previsto: (.+) MB → liberado: (.+) MB · (\d+) removidos · (\d+) preservados$", m => $"Expected: {m.Groups[1].Value} MB → freed: {m.Groups[2].Value} MB · {m.Groups[3].Value} removed · {m.Groups[4].Value} kept"),
        P(@"^ligado há (.+)$", m => $"up for {m.Groups[1].Value}"),
        P(@"^Perfil selecionado: (.+)\. Você sempre revisa os ajustes antes de aplicar\.$", m => $"Selected profile: {T(m, 1)}. You always review the tweaks before applying."),
        P(@"^Perfil ativo: (.+)$", m => $"Active profile: {T(m, 1)}"),
        P(@"^Backup pendente: (.+)$", m => $"Pending backup: {T(m, 1)}"),
        P(@"^(\d+) itens registrados$", m => $"{m.Groups[1].Value} items recorded"),
        P(@"^(.+) · (\d+) ativas$", m => $"{T(m, 1)} · {m.Groups[2].Value} active"),
        P(@"^(.+)  (\d+)$", m => $"{T(m, 1)}  {m.Groups[2].Value}"),
        P(@"^(.+) \((\d+)\)$", m => $"{T(m, 1)} ({m.Groups[2].Value})"),
        P(@"^Exibindo (\d+) de (\d+) otimizações configuradas\.$", m => $"Showing {m.Groups[1].Value} of {m.Groups[2].Value} configured optimizations."),
        P(@"^(.+) — concluído\. Confira os resultados na atividade\.$", m => $"{T(m, 1)} — done. Check the results in the activity log."),
        P(@"^(.+) — cancelado\. O que já foi aplicado aparece em Atividade e reversão\.$", m => $"{T(m, 1)} — cancelled. What was already applied shows up in Activity & restore."),
        P(@"^Operação cancelada pelo usuário: (.+)$", m => $"Operation cancelled by the user: {m.Groups[1].Value}"),
        P(@"^Erro inesperado: (.+)$", m => $"Unexpected error: {m.Groups[1].Value}"),
        P(@"^Erro em segundo plano: (.+)$", m => $"Background error: {m.Groups[1].Value}"),
        P(@"^Erro fatal: (.+)$", m => $"Fatal error: {m.Groups[1].Value}"),
        P(@"^Link inválido: (.*)$", m => $"Invalid link: {m.Groups[1].Value}"),
        P(@"^Link ignorado \(não é um endereço da web\): (.*)$", m => $"Link ignored (not a web address): {m.Groups[1].Value}"),
        P(@"^Não foi possível abrir o navegador: (.+)$", m => $"Could not open the browser: {m.Groups[1].Value}"),
        P(@"^Não foi possível abrir a pasta: (.+)$", m => $"Could not open the folder: {m.Groups[1].Value}"),
        P(@"^Não foi possível abrir a entrada: (.+)$", m => $"Could not open the entry: {m.Groups[1].Value}"),
        P(@"^Agendador de Tarefas (\\.*)$", m => $"Task Scheduler {m.Groups[1].Value}"),
        P(@"^(\d+) ativos?$", m => $"{m.Groups[1].Value} enabled"),
        P(@"^(\d+) desativados?$", m => $"{m.Groups[1].Value} disabled"),
        P(@"^(\d+) (?:item do Windows oculto|itens do Windows ocultos)$", m => $"{m.Groups[1].Value} Windows {(m.Groups[1].Value == "1" ? "entry" : "entries")} hidden"),
        P(@"^(\d+) sem assinatura válida$", m => $"{m.Groups[1].Value} without a valid signature"),
        P(@"^(\d+) (?:arquivo não encontrado|arquivos não encontrados)$", m => $"{m.Groups[1].Value} {(m.Groups[1].Value == "1" ? "file" : "files")} not found"),
        P(@"^Desativar o início automático de ""(.+)""\?\s+O serviço passa para Manual: só inicia quando algum programa precisar dele\. Drivers, antitrapaças e jogos podem depender de serviços; se algo parar de funcionar, marque o item de novo\.$",
