        P(@"^""(.+)"" faz parte do Windows\. Desativar pode afetar recursos do sistema\.\s+Deseja continuar\?$", m => $"\"{m.Groups[1].Value}\" is part of Windows. Disabling it may affect system features.\n\nContinue?"),
        P(@"^Inicialização: não foi possível verificar as assinaturas digitais: (.+)$", m => $"Startup: could not verify digital signatures: {m.Groups[1].Value}"),
        P(@"^Inicialização: não foi possível ler (.+?): (.+)$", m => $"Startup: could not read {T(m, 1)}: {m.Groups[2].Value}"),
        P(@"^cerca de (.+) restantes$", m => $"about {m.Groups[1].Value} left"),
        P(@"^Ativado: (.+)$", m => $"Activated: {T(m, 1)}"),
        P(@"^Modo de energia alterado: (.+)$", m => $"Power mode changed: {T(m, 1)}"),
        P(@"^O Windows recusou a troca do (plano|modo) de energia \(código (\d+)\)\.$", m => $"Windows refused to change the power {(m.Groups[1].Value == "plano" ? "plan" : "mode")} (code {m.Groups[2].Value})."),
        P(@"^Atalho de modo de energia: (.+)$", m => $"Power mode shortcut: {m.Groups[1].Value}"),
        P(@"^Modo de energia: (.+)$", m => $"Power mode: {T(m, 1)}"),
        P(@"^Não foi possível detectar a placa de vídeo: (.+)$", m => $"Could not detect the graphics card: {m.Groups[1].Value}"),
        P(@"^Não foi possível salvar suas preferências: (.+)$", m => $"Could not save your preferences: {m.Groups[1].Value}"),
        P(@"^Preferências não foram salvas: (.+)$", m => $"Preferences were not saved: {m.Groups[1].Value}"),
        P(@"^(\d+) concluídos$", m => $"{m.Groups[1].Value} done"),
        P(@"^(\d+) falhas$", m => $"{m.Groups[1].Value} failures"),
        P(@"^(\d+) avisos$", m => $"{m.Groups[1].Value} warnings"),
        P(@"^(\d+) de (\d+) ativos$", m => $"{m.Groups[1].Value} of {m.Groups[2].Value} enabled"),
        P(@"^(.+): (ativado|desativado) na inicialização\.$", m => $"{m.Groups[1].Value}: {(m.Groups[2].Value == "ativado" ? "enabled" : "disabled")} at startup."),
        P(@"^Não foi possível alterar este item: (.+)$", m => $"Could not change this item: {m.Groups[1].Value}"),
        P(@"^Versão (v[\d.]+)$", m => $"Version {m.Groups[1].Value}"),
        P(@"^Versão atual (v[\d.]+)$", m => $"Current version {m.Groups[1].Value}"),
        P(@"^Válida até (.+)$", m => $"Valid until {m.Groups[1].Value}"),
        P(@"^Sua licença expirou em (.+)\.$", m => $"Your license expired on {m.Groups[1].Value}."),
        P(@"^Até (\S+) \((\d+) dias\)$", m => $"Until {m.Groups[1].Value} ({m.Groups[2].Value} days)"),
