        P(@"^(.+) \(Ativo\)$", m => $"{T(m, 1)} (Active)"),
        P(@"^ISO '(.+)' adicionada com sucesso!$", m => $"ISO '{m.Groups[1].Value}' added!"),
        P(@"^A imagem ISO foi montada na unidade (.+) e aberta no Explorador de Arquivos\.$", m => $"The ISO image was mounted as drive {m.Groups[1].Value} and opened in File Explorer."),
        P(@"^O arquivo ISO não foi localizado:\s*(.+)$", m => $"The ISO file was not found:\n{m.Groups[1].Value}"),
        P(@"^Localizar arquivo para (.+)$", m => $"Find file for {m.Groups[1].Value}"),
        P(@"^Falha ao (abrir navegador|aplicar alteração|desmontar ISO|montar ISO|iniciar o instalador): (.+)$", m => $"Failed to {m.Groups[1].Value switch { "abrir navegador" => "open the browser", "aplicar alteração" => "apply the change", "desmontar ISO" => "unmount the ISO", "montar ISO" => "mount the ISO", _ => "start the installer" }}: {m.Groups[2].Value}"),
        P(@"^Não foi possível abrir (.+)\.$", m => $"Could not open {T(m, 1)}."),
        P(@"^Não foi possível (alterar os atalhos|reiniciar na BIOS): (.+)$", m => $"{(m.Groups[1].Value.StartsWith("alterar") ? "Could not change the shortcuts" : "Could not restart into BIOS")}: {m.Groups[2].Value}"),
        P(@"^Limpeza concluída\. (.+) MB liberados$", m => $"Cleanup finished. {m.Groups[1].Value} MB freed"),
        P(@"^(.+) — (.+) MB · (\d+) arquivos$", m => $"{T(m, 1)} — {m.Groups[2].Value} MB · {m.Groups[3].Value} files"),

        // Saída do script
        P(@"^(.+) \(falhou ou nao se aplica neste PC\)$", m => $"{T(m, 1)} (failed or doesn't apply to this PC)"),
        P(@"^Resumo: (\d+) aplicado\(s\), (\d+) pulado\(s\), (\d+) falha\(s\)$", m => $"Summary: {m.Groups[1].Value} applied, {m.Groups[2].Value} skipped, {m.Groups[3].Value} failed"),
        P(@"^Resumo: (\d+) aplicado\(s\), (\d+) falha\(s\)$", m => $"Summary: {m.Groups[1].Value} applied, {m.Groups[2].Value} failed"),
        P(@"^(\d+) item\(ns\) revertido\(s\), (\d+) falha\(s\)$", m => $"{m.Groups[1].Value} item(s) restored, {m.Groups[2].Value} failed"),
        P(@"^Ultima acao executada: (.+)$", m => $"Last action: {T(m, 1)}"),
        P(@"^Realizada em: (.+)$", m => $"Run on: {m.Groups[1].Value}"),
        P(@"^Itens que serao verificados: (\d+)$", m => $"Items to check: {m.Groups[1].Value}"),
        P(@"^Registro restaurado: (.+)$", m => $"Registry restored: {m.Groups[1].Value}"),
        P(@"^Servico restaurado: (.+)$", m => $"Service restored: {m.Groups[1].Value}"),
        P(@"^Plano de energia restaurado$", _ => "Power plan restored"),
        P(@"^Tarefa reativada: (.+)$", m => $"Task re-enabled: {m.Groups[1].Value}"),
        P(@"^OneDrive: reinstalacao iniciada$", _ => "OneDrive: reinstall started"),
        P(@"^Falha ao reverter: (.*)$", m => $"Failed to restore: {m.Groups[1].Value}"),
        P(@"^Item de backup nao reconhecido ou fora da lista permitida: (.*)$", m => $"Unrecognized backup item or outside the allowlist: {m.Groups[1].Value}"),
        P(@"^Arquivo de backup de origem desconhecida isolado: (.+)$", m => $"Backup file of unknown origin quarantined: {m.Groups[1].Value}"),
        P(@"^Backup anterior ilegivel; arquivado em (.+)$", m => $"Previous backup unreadable; archived at {m.Groups[1].Value}"),
        P(@"^Plano Qrz: (\d+) valor\(es\) nao existem neste PC e ficaram no padrao do Windows\.$", m => $"Qrz plan: {m.Groups[1].Value} value(s) don't exist on this PC and kept the Windows default."),
        P(@"^Comando retornou codigo (-?\d+)$", m => $"Command returned code {m.Groups[1].Value}"),
        P(@"^Comando terminou com codigo (-?\d+)\. Consulte a saida para detalhes\.$", m => $"Command ended with code {m.Groups[1].Value}. See the output for details."),
        P(@"^A execução terminou com falhas \(código (-?\d+)\)\. Consulte a atividade e a reversão para alterações parciais\.$", m => $"The run finished with failures (code {m.Groups[1].Value}). Check activity and restore for partial changes."),
        P(@"^Ignorada: (.+)$", m => $"Skipped: {T(m, 1)}"),
        P(@"^Pulado: (.+)$", m => $"Skipped: {T(m, 1)}"),
        P(@"^Não reversível$", _ => "Not reversible"),
        P(@"^([A-Z]:) ignorada \((.+)\) - o Windows ja agenda a otimizacao desta unidade\.$", m => $"{m.Groups[1].Value} skipped ({m.Groups[2].Value}) - Windows already schedules optimization for this drive."),
        P(@"^TRIM executado em ([A-Z]:)$", m => $"TRIM run on {m.Groups[1].Value}"),
        P(@"^Agendador multimidia \(MMCSS\): (\d+) valores padrao do Windows restaurados\.$", m => $"Multimedia scheduler (MMCSS): {m.Groups[1].Value} Windows default values restored."),
        P(@"^(.+) de arquivos temporarios acumulados$", m => $"{m.Groups[1].Value} of accumulated temporary files"),
        P(@"^(\d+) programas iniciando junto com o Windows$", m => $"{m.Groups[1].Value} programs starting with Windows"),
        P(@"^Plano de energia atual: (.+)$", m => $"Current power plan: {m.Groups[1].Value}"),
        P(@"^Use a Limpeza rapida para liberar (.+)$", m => $"Use Quick cleanup to free {m.Groups[1].Value}"),
        P(@"^Servico Windows Update: (.+) \(StartType: (.+)\)$", m => $"Windows Update service: {m.Groups[1].Value} (StartType: {m.Groups[2].Value})"),
        P(@"^Ultima inicializacao: (.+) s$", m => $"Last boot: {m.Groups[1].Value} s"),
        P(@"^Espaco usado: (\d+)%$", m => $"Used space: {m.Groups[1].Value}%"),
        P(@"^(SSD|HDD) - (\d+)% livre de (.+)$", m => $"{m.Groups[1].Value} - {m.Groups[2].Value}% free of {m.Groups[3].Value}"),
        P(@"^Data anterior : (.+)$", m => $"Previous date : {m.Groups[1].Value}"),
        P(@"^RAM em uso    : (.+)$", m => $"RAM in use    : {m.Groups[1].Value}"),
        P(@"^Disco usado   : (.+)$", m => $"Disk used     : {m.Groups[1].Value}"),
        P(@"^Leitura disco : (.+)$", m => $"Disk read     : {m.Groups[1].Value}"),
        P(@"^Escrita disco : (.+)$", m => $"Disk write    : {m.Groups[1].Value}"),
        P(@"^Boot          : (.+)$", m => $"Boot          : {m.Groups[1].Value}"),
        P(@"^Servico (.+) nao existe neste Windows; nada a fazer\.$", m => $"Service {m.Groups[1].Value} doesn't exist on this Windows; nothing to do."),
        P(@"^Tarefa (.+) nao existe neste Windows; nada a fazer\.$", m => $"Task {m.Groups[1].Value} doesn't exist on this Windows; nothing to do."),
        P(@"^O desinstalador do OneDrive retornou codigo (-?\d+)$", m => $"The OneDrive uninstaller returned code {m.Groups[1].Value}"),
        P(@"^(CPU|RAM) em uso agora: (\d+)%$", m => $"{m.Groups[1].Value} in use now: {m.Groups[2].Value}%"),
        P(@"^(.+): modo MSI ja ativo\.$", m => $"{m.Groups[1].Value}: MSI mode already on."),
        P(@"^(.+): modo MSI ativado \(vale apos reiniciar\)\.$", m => $"{m.Groups[1].Value}: MSI mode enabled (takes effect after restart)."),
        P(@"^Latencia DPC/interrupcoes alta \((.+)% da CPU\)$", m => $"High DPC/interrupt latency ({m.Groups[1].Value}% of CPU)"),
        P(@"^Temperatura alta: (\d+) C - verifique cooling e pasta termica$", m => $"High temperature: {m.Groups[1].Value} C - check cooling and thermal paste"),
        P(@"^Memoria rodando a (\d+) MT/s, mas o kit suporta (\d+) MT/s \(XMP/EXPO desligado na BIOS\)$", m => $"Memory running at {m.Groups[1].Value} MT/s, but the kit supports {m.Groups[2].Value} MT/s (XMP/EXPO off in the BIOS)"),
        P(@"^BIOS com (.+) anos - pode haver versao mais nova no site da placa-mae$", m => $"BIOS is {m.Groups[1].Value} years old - a newer version may be on the motherboard's website"),
        P(@"^DPC: (.+)% da CPU$", m => $"DPC: {m.Groups[1].Value}% of CPU"),
        P(@"^Interrupcoes: (.+)% da CPU \((.+)/s\)$", m => $"Interrupts: {m.Groups[1].Value}% of CPU ({m.Groups[2].Value}/s)"),
        P(@"^Temperatura: (\d+) C \(sensor ACPI\)$", m => $"Temperature: {m.Groups[1].Value} C (ACPI sensor)"),
        P(@"^Latencia DPC  : (.+)$", m => $"DPC latency   : {m.Groups[1].Value}"),
        P(@"^Interrupcoes  : (.+)$", m => $"Interrupts    : {m.Groups[1].Value}"),
        P(@"^Temperatura   : (.+)$", m => $"Temperature   : {m.Groups[1].Value}"),
        P(@"^(Latencia DPC|Modo MSI|Placa-mae|Nucleos|Memoria|Temperatura)(\s+)(.+)$", m => $"{Tr(m.Groups[1].Value)}{m.Groups[2].Value}{m.Groups[3].Value.Replace(" nucleos / ", " cores / ").Replace("pente(s)", "stick(s)").Replace("Interrupcoes", "Interrupts").Replace(": desativado", ": off").Replace(": ativo", ": on").Replace("(sensor ACPI)", "(ACPI sensor)")}"),
        P(@"^(CPU|RAM|DISCO|INICIALIZACAO|WINDOWS|Disco|GPU)(\s+)(.+)$", m => $"{Tr(m.Groups[1].Value)}{m.Groups[2].Value}{m.Groups[3].Value}"),
    };
}
